SELECT EXISTS (
SELECT 1
FROM profile_shops ps
INNER JOIN shops s ON ps.shop_id = s.shop_id
WHERE ps.profile_id = #{currentUserId}
AND ps.shop_id = #{currentUserShopId}
AND ps.deleted_at IS NULL
AND s.deleted_at IS NULL
)

SELECT EXISTS (
SELECT 1
FROM drink_categories
WHERE LOWER(TRIM(category_name)) = LOWER(TRIM(#{categoryName}))
AND shop_id = #{shopId}
AND deleted_at IS NULL

  AND drink_category_id != #{categoryId}

)

